t_number }}</a></td><td><span class="badge {{ $statusClasses[$return->status] ?? 'app-status-neutral' }}">{{ $statusLabels[$return->status] ?? $return->status }}</span> @if($return->status === 'DRAFT' && auth()->user()->hasPermission('production.execution.prepare'))<button class="btn btn-sm btn-app-soft js-wo-action ms-2" type="button" data-url="{{ route('production.orders.material-returns.approve', [$order, $return]) }}">อนุมัติ</button>@endif @if($return->status === 'APPROVED' && auth()->user()->hasPermission('production.execution.post'))<button class="btn btn-sm btn-app-primary js-wo-action ms-2" type="button" data-url="{{ route('production.orders.material-returns.post', [$order, $return]) }}">ลง Stock</button>@endif @if($return->status === 'POSTED' && auth()->user()->hasPermission('production.execution.reverse'))<button class="btn btn-sm btn-app-danger js-reverse-material-return ms-2" type="button" data-url="{{ route('production.orders.material-returns.reverse', [$order, $return]) }}">ยกเลิกเอกสาร</button>@endif</td></tr>@endforeach @foreach($scrapReceipts as $scrap)<tr><td>ใบรับเศษผลิต</td><td>{{ $scrap->document_number }}</td><td><span class="badge {{ $statusClasses[$scrap->status] ?? 'app-status-neutral' }}">{{ $statusLabels[$scrap->status] ?? $scrap->status }}</span> @if($scrap->status === 'DRAFT' && auth()->user()->hasPermission('production.execution.prepare'))<button class="btn btn-sm btn-app-soft js-wo-action ms-2" type="button" data-url="{{ route('production.orders.recoverable-scrap-receipts.approve', [$order, $scrap]) }}">อนุมัติ</button>@endif @if($scrap->status === 'APPROVED' && auth()->user()->hasPermission('production.execution.post'))<button class="btn btn-sm btn-app-primary js-wo-action ms-2" type="button" data-url="{{ route('production.orders.recoverable-scrap-receipts.post', [$order, $scrap]) }}">ลง Stock</button>@endif @if($scrap->status === 'POSTED' && auth()->user()->hasPermission('production.execution.reverse'))<button class="btn btn-sm btn-app-danger js-reverse-scrap ms-2" type="button" data-url="{{ route('production.orders.recoverable-scrap-receipts.reverse', [$order, $scrap]) }}">ยกเลิกเอกสาร</button>@endif</td></tr>@endforeach @foreach($finishedReceipts as $receipt)@php($ready = $finishedReceiptReadiness->get($receipt->id))<tr><td>ใบรับสินค้าผลิตเสร็จ</td><td>@if($canViewFinishedReceipt)<a href="{{ route('wms.production.finished-receipts.show', $receipt) }}">{{ $receipt->document_number }}</a>@else{{ $receipt->document_number }}@endif</td><td><span class="badge {{ $statusClasses[$receipt->status] ?? 'app-status-neutral' }}">{{ $statusLabels[$receipt->status] ?? $receipt->status }}</span> @if($receipt->status === 'DRAFT' && auth()->user()->hasPermission('production.execution.prepare'))<button class="btn btn-sm btn-app-soft js-wo-action ms-2" type="button" data-url="{{ route('production.orders.finished-receipts.approve', [$order, $receipt]) }}">อนุมัติ</button>@endif @if($receipt->status === 'APPROVED' && auth()->user()->hasPermission('production.execution.post'))<button class="btn btn-sm btn-app-primary js-wo-action ms-2" type="button" data-url="{{ route('production.orders.finished-receipts.post', [$order, $receipt]) }}" @disabled(!($ready['ready'] ?? false))>ลง Stock</button>@if(!($ready['ready'] ?? true))<div class="small text-danger mt-1">Posting blocker: {{ collect($ready['blockers'] ?? [])->pluck('message')->filter()->implode(' ') }}</div>@endif @endif @if($receipt->status === 'POSTED' && $receipt->reversal_status !== 'REVERSED' && auth()->user()->hasPermission('production.execution.reverse'))<button class="btn btn-sm btn-app-danger js-reverse-finished-receipt ms-2" type="button" data-url="{{ route('production.orders.finished-receipts.reverse', [$order, $receipt]) }}">ยกเลิกเอกสาร</button>@endif</td></tr>@endforeach @if(! $materialIssue && $materialReturns->isEmpty() && $scrapReceipts->isEmpty() && $finishedReceipts->isEmpty())<tr><td colspan="3" class="text-secondary">ยังไม่มีเอกสาร WMS ที่เกี่ยวข้อง</td></tr>@endif</tbody></table></div></div></div>
    <div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5 mb-3">Audit timeline</h2>@php($eventLabels = ['created'=>'สร้าง WO','released'=>'Release WO','materials_reserved'=>'จองวัตถุดิบ','material_issue_created'=>'สร้างใบเบิกวัตถุดิบ','material_issue_posted'=>'ลง Stock ใบเบิก','material_issue_cancelled'=>'ยกเลิกใบเบิก','material_issue_deleted'=>'ลบใบเบิก','material_return_posted'=>'รับคืนวัตถุดิบ','material_return_reversed'=>'กลับรายการรับคืน','recoverable_scrap_receipt_created'=>'สร้างใบรับเศษผลิต','scrap_receipt_posted'=>'ลง Stock เศษผลิต','scrap_receipt_reversed'=>'กลับรายการเศษผลิต','non_recoverable_scrap_reported'=>'บันทึกของเสียไม่มีมูลค่า','finished_receipt_posted'=>'รับผลิตเสร็จ','finished_receipt_reversed'=>'กลับรายการรับผลิต','finished_goods_reserved'=>'จองสินค้าสำเร็จรูป','cancelled'=>'ยกเลิก WO'])@forelse($order->events->sortByDesc('occurred_at') as $event)<div class="border-bottom py-2"><div class="d-flex flex-wrap justify-content-between gap-2"><strong>{{ $eventLabels[$event->event_type] ?? $event->event_type }}</strong><span class="text-secondary small">{{ $event->occurred_at?->format('d/m/Y H:i') ?: '—' }}</span></div><div class="small text-secondary">โดย {{ $event->creator?->name ?: 'ระบบ' }}@if($event->source_id) · {{ $event->source_type ? class_basename($event->source_type) : 'source' }} #{{ $event->source_id }}@endif</div>@if($event->payload)<div class="small mt-1"><code>{{ json_encode($event->payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) }}</code></div>@endif</div>@empty<div class="text-secondary">ยังไม่มีเหตุการณ์</div>@endforelse</div></div>
    @if($materialIssue?->status === 'POSTED' && auth()->user()->hasPermission('production.execution.prepare'))<div class="modal fade" id="material-return-modal" tabindex="-1" aria-labelledby="material-return-title" aria-hidden="true"><div class="modal-dialog"><form class="modal-content" id="material-return-form" data-url="{{ route('production.orders.material-return', $order) }}"><div class="modal-header"><h2 class="modal-title fs-5" id="material-return-title">สร้างใบรับคืนวัตถุดิบ</h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="ปิด"></button></div><div class="modal-body"><p class="text-secondary small">ระบบจะสร้างจากจำนวนวัตถุดิบที่ยังรับคืนได้ทั้งหมด</p><label class="form-label" for="material-return-reason">เหตุผล <span class="text-danger">*</span></label><textarea class="form-control" id="material-return-reason" name="reason" required minlength="10" maxlength="500">คืนวัตถุดิบจาก WO {{ $order->document_number }}</textarea><div class="invalid-feedback"></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">ปิด</button><button class="btn btn-app-primary" type="submit"><i class="bx bx-undo me-1" aria-hidden="true"></i>สร้างใบรับคืนวัตถุดิบ</button></div></form></div></div>@endif
</div>
