@push('scripts')
<script>
$(function(){
    const token=$('meta[name="csrf-token"]').attr('content');
    const error=x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat()[0]||x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'});
    const confirmAction=(title,text)=>Swal.fire({icon:'warning',title,text,showCancelButton:true,confirmButtonText:title.replace(/\?$/,'').replace('ใบสั่งผลิตนี้',''),cancelButtonText:'กลับไปตรวจสอบ'}).then(r=>r.isConfirmed);
    const ask=(title,input='text',value='')=>Swal.fire({title,input,inputValue:value,showCancelButton:true,confirmButtonText:'ถัดไป',cancelButtonText:'ยกเลิก'}).then(r=>r.isConfirmed?r.value:null);
    const post=(button,data={})=>$.post(button.data('url'),{_token:token,...data}).done(r=>{window.location=r.redirect;}).fail(error);
    $(document).on('click','.js-wo-action',async function(){const b=$(this);if(b.prop('disabled'))return;let data={};if(b.text().trim()==='ยกเลิกเอกสาร'){if(!await confirmAction('ยกเลิกเอกสาร?','ยกเลิกเอกสารโดยเก็บประวัติไว้; ถ้ายังเป็นร่างและต้องการลบ ให้ใช้ “ลบร่าง” แทน'))return;const reason=await ask('เหตุผลยกเลิกเอกสาร','textarea');if(!reason||reason.trim().length<10){if(reason!==null)await Swal.fire({icon:'warning',text:'ระบุเหตุผลอย่างน้อย 10 ตัวอักษร'});return;}data.reason=reason.trim();}b.prop('disabled',true);post(b,data).fail(()=>b.prop('disabled',false));});
    $(document).on('click','.js-wo-delete',async function(){if(!await confirmAction('ลบร่างใบสั่งผลิตนี้?','ลบร่างที่ยังไม่ดำเนินงาน; หากต้องการเก็บประวัติให้ใช้ “ยกเลิกเอกสาร” แทน'))return;const b=$(this).prop('disabled',true);post(b,{_method:'DELETE'}).fail(()=>b.prop('disabled',false));});
    const sourceMaterial=async btn=>{const lines=btn.data('material-lines')||[],hint=lines.length?'\n'+lines.map(x=>x.id+': '+x.label).join('\n'):'';return await ask('Material line ต้นทาง (เว้นว่างได้)','text',hint)||null;};
    $(document).on('click','.js-nonrecoverable-scrap',async function(){const b=$(this),qty=await ask('จำนวนของเสียไม่มีมูลค่า','number');if(!qty)return;const reason=await ask('เหตุผล','textarea');if(!reason)return;const source=await sourceMaterial(b);b.prop('disabled',true);post(b,{quantity:qty,uom_id:b.data('uom-id'),source_material_line_id:source,reason}).fail(()=>b.prop('disabled',false));});
    $(document).on('click','.js-recoverable-scrap',async function(){
        const b=$(this);
        const result=await Swal.fire({title:'รับเศษผลิต',html:'<label class="form-label d-block text-start" for="scrap-item">สินค้าเศษ (ค้นหารหัสหรือชื่อ)</label><select id="scrap-item" class="form-select"></select><div id="scrap-item-uom" class="form-text text-start mb-2"></div><label class="form-label d-block text-start" for="scrap-quantity">จำนวน</label><input id="scrap-quantity" class="form-control mb-2" type="number" min="0.00000001" step="0.00000001"><label class="form-label d-block text-start" for="scrap-value">มูลค่ารับเศษรวม</label><input id="scrap-value" class="form-control mb-2" type="number" min="0.00000001" step="0.00000001"><label class="form-label d-block text-start" for="scrap-reason">เหตุผล</label><textarea id="scrap-reason" class="form-control" maxlength="500" rows="3"></textarea>',showCancelButton:true,confirmButtonText:'ถัดไป',cancelButtonText:'ยกเลิก',didOpen:()=>{const select=$('#scrap-item');window.erpInitSelect2(select,{dropdownParent:$(Swal.getPopup()),placeholder:'ค้นหาสินค้าเศษ',minimumInputLength:0,ajax:{url:b.data('options-url'),delay:250,data:params=>({q:params.term||'',page:params.page||1}),processResults:data=>data}});select.on('select2:select',event=>$('#scrap-item-uom').text('หน่วย: '+event.params.data.uom_label));},preConfirm:()=>{const item=$('#scrap-item').select2('data')[0],quantity=$('#scrap-quantity').val(),value=$('#scrap-value').val(),reason=$('#scrap-reason').val().trim();if(!item||!quantity||Number(quantity)<=0||!value||Number(value)<=0||reason.length<10){Swal.showValidationMessage('เลือกสินค้า ระบุจำนวน/มูลค่ามากกว่า 0 และเหตุผลอย่างน้อย 10 ตัวอักษร');return false;}return {scrap_item_id:item.id,uom_id:item.uom_id,quantity,recovery_total_value:value,reason};}});
        if(!result.isConfirmed)return;
        const source=await sourceMaterial(b);b.prop('disabled',true);post(b,{...result.value,source_material_line_id:source}).fail(()=>b.prop('disabled',false));
    });
    $(document).on('click','.js-finished-receipt',async function(){const b=$(this),reason=await ask('เหตุผลการรับผลิตเสร็จ','textarea','รับสินค้าผลิตเสร็จจาก WO');if(reason===null)return;b.prop('disabled',true);post(b,{reason:reason||'รับสินค้าผลิตเสร็จจาก WO'}).fail(()=>b.prop('disabled',false));});
    $(document).on('submit','#material-return-form',function(e){e.preventDefault();const form=$(this),b=form.find('[type="submit"]').prop('disabled',true),reason=form.find('[name="reason"]');$.post(form.data('url'),{_token:token,reason:reason.val()}).done(r=>{window.location=r.redirect;}).fail(x=>{reason.addClass('is-invalid').siblings('.invalid-feedback').text((x.responseJSON||{}).message||'สร้างใบรับคืนไม่สำเร็จ');b.prop('disabled',false);});});
    async function reverse(button,extra={}){const reason=await ask('เหตุผลยกเลิกเอกสาร','textarea');if(!reason)return;button.prop('disabled',true);post(button,{...extra,reason}).fail(()=>button.prop('disabled',false));}
    $(document).on('click','.js-reverse-scrap',function(){reverse($(this),{reversal_date:new Date().toISOString().slice(0,10)});});
    $(document).on('click','.js-reverse-finished-receipt',function(){reverse($(this),{reversal_date:new Date().toISOString().slice(0,10)});});
    $(document).on('click','.js-reverse-material-issue,.js-reverse-material-return',async function(){const b=$(this);let extra={};if(b.data('needs-material-confirm')){const ack=await Swal.fire({icon:'warning',title:'ยืนยันการคืนวัตถุดิบ',text:'การกลับรายการใบเบิกจะนำวัตถุดิบทั้งหมดกลับเข้าคลัง ต้องยืนยันว่าไม่ได้ใช้ผลิตและคืนคลังได้จริง',input:'checkbox',inputPlaceholder:'ยืนยันว่าวัตถุดิบยังไม่ถูกใช้และคืนคลังได้ครบ',showCancelButton:true,confirmButtonText:'ดำเนินการต่อ',cancelButtonText:'กลับไปตรวจสอบ',preConfirm:value=>{if(!value)Swal.showValidationMessage('กรุณายืนยันก่อนดำเนินการ');return value;}});if(!ack.isConfirmed)return;extra.materials_returnable=1;}reverse(b,extra);});
});
</script>
@endpush
